SCENARIOS: dict[str, list[dict[str, Any]]] = {"S11": S11, "S12": S12, "S13": S13, "S14": S14, "S15": S15}
FAMILY = {"S11":"offsite confirmation under recovery stack", "S12":"demo rehearsal versus voice clarity", "S13":"APAC verbal ownership under incomplete records", "S14":"hot-desking versus quiet compliance drafting", "S15":"overnight Sev-1 leadership under sleep debt"}
BANNED_VISIBLE_TERMS = {"calibration", "constraint", "evidence", "target", "latent", "connector", "infer", "conclusion", "annotation", "criterion", "benchmark", "arm", "schema", "hypothesis"}
KEY_FIELDS = ("cx1", "cx2", "a", "e1", "b", "e2", "lure", "bprime")

def build_context(sp: dict[str, Any], s_idx: int, u_idx: int, user_id: str) -> list[dict[str, Any]]:
    start = datetime(2032, 1, 3, tzinfo=timezone.utc) + timedelta(days=(s_idx * 10 + u_idx) * 37)
    sessions = []
    for session_id in range(1, 21):
        turns = (base.fill(base.BG[base.SLOT_BG[session_id]], sp["props"]) if session_id in base.SLOT_BG else sp[{3:"cx1",6:"a",7:"cx2",9:"e1",14:"b",17:"e2"}.get(session_id, "query")] if session_id in (3,6,7,9,14,17) else [{"role":"user","content":sp["query"]}])
        stamp = start + timedelta(days=session_id - 1, hours=base.HOURS[session_id % len(base.HOURS)])
        sessions.append({"session_id":session_id,"timestamp":stamp.strftime("%Y-%m-%dT%H:%M:00Z"),"speaker_id":user_id,"speaker_label":"User","dialogue":[dict(t) for t in turns]})
    return sessions

def all_prior_lines() -> set[str]:
    lines: set[str] = set()
    for directory in (HERE / "candidates-s1-s5-review", HERE / "candidates-s6-s10-review"):
        for path in directory.glob("*/*.json"):
            item = json.loads(path.read_text(encoding="utf-8"))
            for session in item["context"]:
                lines.update(t["content"].strip().lower() for t in session["dialogue"])
    return lines

def audit() -> list[str]:
    """Reject incomplete, reused, meta-visible, or date-colliding profiles."""
    problems: list[str] = []
    prior = all_prior_lines(); seen: set[str] = set(); timestamps: set[str] = set()
    for sid, specs in SCENARIOS.items():
        for sp in specs:
            for field in ("cx1", "cx2", "a", "e1", "b", "e2", "lure", "bprime", "query"):
                turns = sp[field] if field != "query" else [{"content": sp[field]}]
                if field != "query" and len(turns) != 3: problems.append(f"{sid}/{sp['uid']} incomplete {field}")
                for turn in turns:
                    text = turn["content"].strip(); key = text.lower()
                    if not text: problems.append(f"{sid}/{sp['uid']} empty {field}")
                    if key in prior: problems.append(f"{sid}/{sp['uid']} repeats S1-S10 {field}")
                    if key in seen: problems.append(f"{sid}/{sp['uid']} repeats S11-S15 {field}")
                    if any(re.search(rf"\b{re.escape(word)}\b", text, re.I) for word in BANNED_VISIBLE_TERMS): problems.append(f"{sid}/{sp['uid']} forbidden visible word")
                    seen.add(key)
            for session in build_context(sp, list(SCENARIOS).index(sid), int(sp['uid'][1:]) - 1, sp['uid']):
                if session['timestamp'] in timestamps: problems.append(f"duplicate timestamp {session['timestamp']}")
                timestamps.add(session['timestamp'])
    return problems

def write_readme() -> None:
    lines=["# Work S11-S15 review batch", "", "50 explicit operational profiles; 150 generated JSON files.", "", "| Scenario | User | Role | Query type | Polarity | A | B | E1 | E2 | Calibrated result |", "|---|---|---|---|---|---|---|---|---|---|"]
    for sid, specs in SCENARIOS.items():
        for sp in specs:
            short=lambda name: sp[name][0]['content'].split('.')[0]
            lines.append(f"| {sid} | {sp['uid']} | {sp['role']} | {sp['query_type']} | {sp['polarity']} | {short('a')} | {short('b')} | {short('e1')} | {short('e2')} | {sp['calibrated']} |")
    (OUT / "README.md").write_text("\n".join(lines)+"\n",encoding="utf-8")

def main() -> int:
    problems=audit()
    if problems: raise SystemExit("BATCH AUDIT FAILED:\n"+"\n".join(f"- {p}" for p in problems))
    base.FAMILY.update(FAMILY); base.build_context=build_context
    for arm in ("associative","distractor","absence"): (OUT/arm).mkdir(parents=True,exist_ok=True)
    records=[]; rendered=0
    for s_idx,(sid,specs) in enumerate(SCENARIOS.items()):
        for u_idx,sp in enumerate(specs):
            for arm in ("associative","distractor","absence"):
                item=base.build_item(sid,s_idx,sp,u_idx,arm); score,notes=base.score_item(item); errors=validate_candidate(item)
                if score<95 or errors: raise RuntimeError(f"rejected {item['candidate_id']}: {score} {notes} {errors}")
                (OUT/arm/f"{item['candidate_id']}.json").write_text(json.dumps(item,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
                records.append({"candidate_id":item['candidate_id'],"arm":arm,"score":score,"schema_errors":errors})
                if arm=="associative":
                    variants=render_arms(item)
                    if set(variants)!={"full","a_only","b_only","link_broken"}: raise RuntimeError(f"render failure {item['candidate_id']}")
                    rendered+=1
    payload={"batch":"S11-S15","records":records,"deterministic_passed":len(records),"schema_validated":len(records),"rendered_associative":rendered}
    AUDIT_PATH.parent.mkdir(parents=True,exist_ok=True); AUDIT_PATH.write_text(json.dumps(payload,indent=2)+"\n",encoding="utf-8"); write_readme()
    print(f"PASS {len(records)}/150; schema={len(records)}/150; rendered={rendered}/50")
    return 0
if __name__ == "__main__": raise SystemExit(main())
